// Runs every check this project has. Passing it is the definition of done.
// Plain Node: read it, change it, or run each command yourself.
import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { delimiter, join } from "node:path";
import { requireGeneratedClients } from "./clients.mjs";

// Find the project's own binaries even when this script is run without `npm run`.
const env = {
  ...process.env,
  PATH: `${join("node_modules", ".bin")}${delimiter}${process.env.PATH}`,
};

requireGeneratedClients();

const steps = [
  { name: "Typecheck", command: "next typegen && tsc --noEmit" },
  { name: "Lint", command: 'eslint --ignore-pattern "packages/**"' },
];
if (existsSync("contracts/Cargo.toml")) {
  steps.push({ name: "Contract tests", command: "cargo test", cwd: "contracts" });
}
steps.push({ name: "Build", command: "next build" });

for (const step of steps) {
  const where = step.cwd ? ` (in ${step.cwd}/)` : "";
  console.log(`\n> ${step.name}: ${step.command}${where}`);
  const result = spawnSync(step.command, { stdio: "inherit", shell: true, cwd: step.cwd, env });
  if (result.status !== 0) {
    console.error(
      `\n✗ ${step.name} failed. Fix the errors above, then run the check script again.`,
    );
    process.exit(result.status ?? 1);
  }
}
console.log("\n✓ All checks passed.");
// Regenerate the typed clients in packages/ from the built contracts. Never edit packages/ by hand.
import { bindings, listContracts, main } from "./stellar.mjs";

main(() => {
  for (const contract of listContracts()) bindings(contract);
});
// Starts the Next.js dev server, plus the contract watcher when this project has contracts.
// Plain Node: read it, change it, or run `next dev` yourself.
import { spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { delimiter, join } from "node:path";
import { requireGeneratedClients } from "./clients.mjs";

// Find the project's own binaries (for the watcher's stellar and npx calls) without `npm run`.
const env = {
  ...process.env,
  PATH: `${join("node_modules", ".bin")}${delimiter}${process.env.PATH}`,
};

requireGeneratedClients();

// Run Next.js's own entry point with Node: no shell, so it behaves the same on every OS.
const nextBin = join("node_modules", "next", "dist", "bin", "next");
if (!existsSync(nextBin)) {
  console.error(
    "✗ Next.js is not installed in this project (node_modules/next is missing). Run your package manager's install (npm install), then rerun.",
  );
  process.exit(1);
}

const children = [];
const stop = () => {
  for (const child of children) child.kill();
};

const next = spawn(process.execPath, [nextBin, "dev", ...process.argv.slice(2)], {
  stdio: "inherit",
  env,
});
children.push(next);
next.on("exit", (code) => {
  stop();
  process.exit(code ?? 0);
});

if (existsSync("contracts/Cargo.toml") && existsSync("scripts/watch-contracts.mjs")) {
  children.push(
    spawn(process.execPath, ["scripts/watch-contracts.mjs"], { stdio: "inherit", env }),
  );
}
process.on("SIGINT", stop);
process.on("SIGTERM", stop);
// Rebuilds, redeploys and regenerates clients when a contract changes. Started by the dev script.
// Never deploys to mainnet. Unchanged contracts are not redeployed.
import { realpathSync, watch } from "node:fs";
import { bindings, build, deploy, listContracts, loadConfig, StepError } from "./stellar.mjs";

const RELEVANT = /(\.rs|Cargo\.toml)$/;

function message(error) {
  return error instanceof Error ? error.message : String(error);
}

let config;
try {
  config = loadConfig();
} catch (error) {
  console.error(`✗ Contract watcher not started: ${message(error)}`);
  process.exit(1);
}
if (config.network === "mainnet") {
  console.log(
    "Contract watcher is off on mainnet. Deploy with the contracts:deploy script and --confirm-mainnet, only when the user asks for it.",
  );
  process.exit(0);
}

let running = false;
let again = false;
let timer;

function rebuild() {
  if (running) {
    again = true;
    return;
  }
  running = true;
  try {
    const current = loadConfig(); // .env may have changed since the watcher started
    if (current.network === "mainnet") {
      throw new StepError("The network is now mainnet. The watcher never deploys to mainnet.");
    }
    build();
    for (const contract of listContracts()) {
      deploy(current, contract, { onlyIfChanged: true, confirmMainnet: false });
      bindings(contract);
    }
    console.log("✓ Contracts rebuilt, deployed and regenerated. Still watching contracts/.");
  } catch (error) {
    console.error(`✗ ${message(error)}\nStill watching contracts/.`);
  } finally {
    running = false;
    if (again) {
      again = false;
      rebuild();
    }
  }
}

// Watch the canonical path. On Windows, a path reached through an 8.3 short name
// (C:\Users\RUNNER~1\...) makes Node's watcher abort, because the events report the long name.
const contractsDir = realpathSync.native("contracts");
watch(contractsDir, { recursive: true }, (_event, file) => {
  const path = String(file ?? "").replace(/\\/g, "/");
  if (!RELEVANT.test(path) || path.split("/").includes("target")) return;
  clearTimeout(timer);
  timer = setTimeout(rebuild, 300);
});
console.log("Watching contracts/ for changes to .rs and Cargo.toml files.");
