#![no_std]
use soroban_sdk::{
    contract, contracterror, contractimpl, contracttype, panic_with_error, token, Address, Env,
};

// Keep staked balances alive for about 30 days after each touch (ledgers are ~5s apart).
const LEDGERS_THRESHOLD: u32 = 17_280 * 7;
const LEDGERS_EXTEND_TO: u32 = 17_280 * 30;

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
#[repr(u32)]
pub enum Error {
    InvalidAmount = 1,
    InsufficientStake = 2,
}

#[contracttype]
pub enum DataKey {
    /// Address of the token contract that is staked (the native XLM Stellar Asset Contract).
    Token,
    /// Total amount staked by everyone.
    TotalStaked,
    /// Amount staked by one user.
    Staked(Address),
}

#[contract]
pub struct Staking;

#[contractimpl]
impl Staking {
    /// Runs once, at deploy time. Stores the token contract, so the contract is ready to use.
    pub fn __constructor(env: Env, token: Address) {
        env.storage().instance().set(&DataKey::Token, &token);
        env.storage().instance().set(&DataKey::TotalStaked, &0_i128);
    }

    /// Moves `amount` from `user` into the contract and credits it to `user`.
    pub fn stake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::InvalidAmount);
        }

        let token = token_client(&env);
        token.transfer(&user, &env.current_contract_address(), &amount);

        let key = DataKey::Staked(user.clone());
        let current: i128 = env.storage().persistent().get(&key).unwrap_or(0);
        set_staked(&env, &key, current + amount);

        let total: i128 = env.storage().instance().get(&DataKey::TotalStaked).unwrap_or(0);
        env.storage().instance().set(&DataKey::TotalStaked, &(total + amount));
    }

    /// Returns `amount` from the contract to `user`. Fails if `user` has less than `amount` staked.
    pub fn unstake(env: Env, user: Address, amount: i128) {
        user.require_auth();
        if amount <= 0 {
            panic_with_error!(&env, Error::InvalidAmount);
        }

        let key = DataKey::Staked(user.clone());
        let current: i128 = env.storage().persistent().get(&key).unwrap_or(0);
        if current < amount {
            panic_with_error!(&env, Error::InsufficientStake);
        }
        set_staked(&env, &key, current - amount);

        let total: i128 = env.storage().instance().get(&DataKey::TotalStaked).unwrap_or(0);
        env.storage().instance().set(&DataKey::TotalStaked, &(total - amount));

        let token = token_client(&env);
        token.transfer(&env.current_contract_address(), &user, &amount);
    }

    /// The amount `user` has staked.
    pub fn staked(env: Env, user: Address) -> i128 {
        env.storage().persistent().get(&DataKey::Staked(user)).unwrap_or(0)
    }

    /// The amount staked by everyone.
    pub fn total_staked(env: Env) -> i128 {
        env.storage().instance().get(&DataKey::TotalStaked).unwrap_or(0)
    }
}

fn token_client(env: &Env) -> token::TokenClient<'_> {
    let address: Address = env.storage().instance().get(&DataKey::Token).unwrap();
    token::TokenClient::new(env, &address)
}

fn set_staked(env: &Env, key: &DataKey, amount: i128) {
    if amount == 0 {
        env.storage().persistent().remove(key);
    } else {
        env.storage().persistent().set(key, &amount);
        env.storage()
            .persistent()
            .extend_ttl(key, LEDGERS_THRESHOLD, LEDGERS_EXTEND_TO);
    }
}

