#![cfg(test)]
use super::{Staking, StakingClient};
use soroban_sdk::{testutils::Address as _, token, Address, Env};

struct Setup<'a> {
    env: Env,
    staking: StakingClient<'a>,
    token: token::TokenClient<'a>,
    token_admin: token::StellarAssetClient<'a>,
    contract_id: Address,
}

fn setup() -> Setup<'static> {
    let env = Env::default();
    env.mock_all_auths();

    let admin = Address::generate(&env);
    let sac = env.register_stellar_asset_contract_v2(admin);
    let token_id = sac.address();
    let contract_id = env.register(Staking, (&token_id,));

    Setup {
        staking: StakingClient::new(&env, &contract_id),
        token: token::TokenClient::new(&env, &token_id),
        token_admin: token::StellarAssetClient::new(&env, &token_id),
        contract_id,
        env,
    }
}

#[test]
fn stake_moves_tokens_and_tracks_totals() {
    let s = setup();
    let alice = Address::generate(&s.env);
    s.token_admin.mint(&alice, &1_000);

    assert_eq!(s.staking.staked(&alice), 0);
    assert_eq!(s.staking.total_staked(), 0);

    s.staking.stake(&alice, &400);

    assert_eq!(s.staking.staked(&alice), 400);
    assert_eq!(s.staking.total_staked(), 400);
    assert_eq!(s.token.balance(&alice), 600);
    assert_eq!(s.token.balance(&s.contract_id), 400);
}

#[test]
fn totals_include_every_user() {
    let s = setup();
    let alice = Address::generate(&s.env);
    let bob = Address::generate(&s.env);
    s.token_admin.mint(&alice, &1_000);
    s.token_admin.mint(&bob, &1_000);

    s.staking.stake(&alice, &300);
    s.staking.stake(&bob, &200);
    s.staking.stake(&alice, &100);

    assert_eq!(s.staking.staked(&alice), 400);
    assert_eq!(s.staking.staked(&bob), 200);
    assert_eq!(s.staking.total_staked(), 600);
}

#[test]
fn unstake_returns_tokens_and_reduces_stake() {
    let s = setup();
    let alice = Address::generate(&s.env);
    s.token_admin.mint(&alice, &1_000);
    s.staking.stake(&alice, &500);

    s.staking.unstake(&alice, &200);

    assert_eq!(s.staking.staked(&alice), 300);
    assert_eq!(s.staking.total_staked(), 300);
    assert_eq!(s.token.balance(&alice), 700);
    assert_eq!(s.token.balance(&s.contract_id), 300);
}

#[test]
fn unstake_everything_clears_the_stake() {
    let s = setup();
    let alice = Address::generate(&s.env);
    s.token_admin.mint(&alice, &1_000);
    s.staking.stake(&alice, &500);

    s.staking.unstake(&alice, &500);

    assert_eq!(s.staking.staked(&alice), 0);
    assert_eq!(s.staking.total_staked(), 0);
    assert_eq!(s.token.balance(&alice), 1_000);
}

#[test]
fn unstake_more_than_staked_fails() {
    let s = setup();
    let alice = Address::generate(&s.env);
    s.token_admin.mint(&alice, &1_000);
    s.staking.stake(&alice, &100);

    let result = s.staking.try_unstake(&alice, &101);

    assert!(result.is_err());
    assert_eq!(s.staking.staked(&alice), 100);
    assert_eq!(s.staking.total_staked(), 100);
    assert_eq!(s.token.balance(&alice), 900);
}

#[test]
fn unstake_without_any_stake_fails() {
    let s = setup();
    let alice = Address::generate(&s.env);
    s.token_admin.mint(&alice, &1_000);

    assert!(s.staking.try_unstake(&alice, &1).is_err());
}

#[test]
fn non_positive_amounts_are_rejected() {
    let s = setup();
    let alice = Address::generate(&s.env);
    s.token_admin.mint(&alice, &1_000);

    assert!(s.staking.try_stake(&alice, &0).is_err());
    assert!(s.staking.try_stake(&alice, &-5).is_err());
    assert_eq!(s.staking.total_staked(), 0);
}
