"use client";

import { useState, type FormEvent } from "react";
import { requestAccess, signAuthEntry, signTransaction } from "@stellar/varial-sdk";
import { stakingContract, type Signer } from "@/lib/contracts";

type Status = { kind: "idle" } | { kind: "ok"; message: string } | { kind: "error"; message: string };

function errorMessage(error: unknown): string {
  return (error instanceof Error && error.message) || String(error) || "unknown error";
}

/** Whole, positive amount in the token's smallest unit (stroops). */
function parseAmount(text: string): bigint {
  const trimmed = text.trim();
  if (!/^\d+$/.test(trimmed) || BigInt(trimmed) <= 0n) {
    throw new Error("Enter a whole number greater than 0, in stroops (1 XLM = 10000000).");
  }
  return BigInt(trimmed);
}

/** A signer that asks the connected wallet to sign. The wallet reports failures in `error`. */
function walletSigner(publicKey: string): Signer {
  return {
    publicKey,
    signTransaction: async (xdr, opts) => {
      const { signedTxXdr, signerAddress, error } = await signTransaction(xdr, opts);
      if (error) throw new Error(error.message);
      return { signedTxXdr, signerAddress };
    },
    signAuthEntry: async (entry, opts) => {
      const { signedAuthEntry, signerAddress, error } = await signAuthEntry(entry, opts);
      if (error) throw new Error(error.message);
      if (!signedAuthEntry) throw new Error("The wallet did not sign the authorization entry.");
      return { signedAuthEntry, signerAddress };
    },
  };
}

export function StakeForm() {
  const [address, setAddress] = useState<string>();
  const [amount, setAmount] = useState("");
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState<Status>({ kind: "idle" });

  async function connect() {
    setStatus({ kind: "idle" });
    try {
      const { address: publicKey, error } = await requestAccess();
      if (error || !publicKey) {
        throw new Error(error?.message || "The wallet did not return an address.");
      }
      setAddress(publicKey);
    } catch (error) {
      setStatus({ kind: "error", message: `Could not connect a wallet: ${errorMessage(error)}` });
    }
  }

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!address) return;
    setStatus({ kind: "idle" });
    let value: bigint;
    try {
      value = parseAmount(amount);
    } catch (error) {
      setStatus({ kind: "error", message: errorMessage(error) });
      return;
    }
    setBusy(true);
    try {
      const tx = await stakingContract(walletSigner(address)).stake({
        user: address,
        amount: value,
      });
      await tx.signAndSend();
      setStatus({ kind: "ok", message: `Staked ${value.toString()}. Reload to see the new total.` });
      setAmount("");
    } catch (error) {
      setStatus({ kind: "error", message: `Stake failed: ${errorMessage(error)}` });
    } finally {
      setBusy(false);
    }
  }

  return (
    <div>
      {address ? (
        <p>
          Connected: <code data-testid="wallet-address">{address}</code>
        </p>
      ) : (
        <button type="button" data-testid="connect-wallet" onClick={connect}>
          Connect wallet
        </button>
      )}

      <form onSubmit={submit}>
        <label>
          Amount (stroops)
          <input
            data-testid="stake-amount"
            type="text"
            inputMode="numeric"
            placeholder="10000000"
            value={amount}
            onChange={(event) => setAmount(event.target.value)}
            disabled={!address || busy}
          />
        </label>
        <button type="submit" data-testid="stake-submit" disabled={!address || busy}>
          {busy ? "Staking…" : "Stake"}
        </button>
      </form>

      {status.kind === "ok" && <p data-testid="stake-status">{status.message}</p>}
      {status.kind === "error" && <p data-testid="stake-error">{status.message}</p>}
    </div>
  );
}
EOF
